SourceCode.Declaration:
/// <summary>
/// TelemetryShipConfirm class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetryShipConfirm extends METTelemetryBase
{
    private WHSLoadTable load;

}

Method.Source:
protected void populateProperties()
{
    WHSLoadLine loadLine;
    select count(RecId) from loadLine where
        loadLine.LoadId == load.LoadId;

    // Setting elapsed milliseconds in the concrete implementation so that the implementer can decide what is the right way to get elapsed time.
    this.setElapsedMilliseconds();
    this.addBaseProperty(METApplicationInsightsEventProperties::LoadId, load.LoadId);
    this.addBaseProperty(METApplicationInsightsEventProperties::InventLocationId, load.InventLocationId);
    this.addBaseProperty(METApplicationInsightsEventProperties::LoadStatus,strFmt("%1",load.LoadStatus));
    this.addBaseProperty(METApplicationInsightsEventProperties::NumOfLines, int642Str(loadLine.RecId));
}
